const { accessSync, constants } = await import('node:fs');
if (!input.pdf_path) { throw new Error('pdf_path input required'); }
try { accessSync(input.pdf_path, constants.R_OK); } catch { throw new Error('PDF file not accessible'); }
globalThis.pdfPath = input.pdf_path;

const { pdfjs } = await import('react-pdf');
pdfjs.GlobalWorkerOptions.workerSrc = new URL('pdfjs-dist/build/pdf.worker.min.mjs', import.meta.url).toString();
const loadingTask = pdfjs.getDocument({ url: globalThis.pdfPath });
const doc = await loadingTask.promise;
globalThis.numPages = doc.numPages;
